mapper.sql:
c.started_at >= #{fromAt}
AND c.started_at < #{toExclusive}

  AND c.user_id = #{userId}


  AND lower(c.provider) = #{provider}


  AND c.model = #{model}


  AND c.purpose = #{purpose}


  AND c.source = #{source}

mapper.select:
SELECT count(*)
FROM ai_run_admissions a
WHERE a.created_at >= #{fromAt}
  AND a.created_at < #{toExclusive}
  AND a.status IN ('ADMITTED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED', 'EXPIRED')

  AND a.user_id = #{userId}


  AND a.purpose = #{purpose}


  AND a.source = #{source}
